import supabase from '../supabaseClient';

export class WebRTCManager {
  constructor(callId, isInitiator, onRemoteStream, onIceConnectionStateChange) {
    this.callId = callId;
    this.isInitiator = isInitiator;
    this.onRemoteStream = onRemoteStream;
    this.onIceConnectionStateChange = onIceConnectionStateChange;
    this.localStream = null;
    this.peerConnection = null;
    this.channel = null;

    // Configuration with public Google STUN server
    this.configuration = {
      iceServers: [
        { urls: "stun:stun.l.google.com:19302" }
      ]
    };
  }

  async initialize(localStream) {
    this.localStream = localStream;
    this.peerConnection = new RTCPeerConnection(this.configuration);

    // Add local tracks to peer connection
    this.localStream.getTracks().forEach(track => {
      this.peerConnection.addTrack(track, this.localStream);
    });

    // Handle incoming remote stream
    this.peerConnection.ontrack = (event) => {
      if (this.onRemoteStream) {
        this.onRemoteStream(event.streams[0]);
      }
    };

    // Handle ICE connection state changes
    this.peerConnection.oniceconnectionstatechange = () => {
      if (this.onIceConnectionStateChange) {
        this.onIceConnectionStateChange(this.peerConnection.iceConnectionState);
      }
    };

    // Set up Supabase Realtime channel for signaling
    this.channel = supabase.channel(`video-call-${this.callId}`);

    // Listen for signaling messages
    this.channel
      .on('broadcast', { event: 'signal' }, (payload) => {
        this.handleSignalingData(payload.payload);
      })
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          // If this peer is the initiator (Doctor), create and send the offer once subscribed
          if (this.isInitiator) {
            this.createOffer();
          }
        }
      });

    // Send local ICE candidates to the remote peer
    this.peerConnection.onicecandidate = (event) => {
      if (event.candidate) {
        this.sendSignalingData({
          type: 'ice-candidate',
          candidate: event.candidate
        });
      }
    };
  }

  sendSignalingData(data) {
    if (this.channel) {
      this.channel.send({
        type: 'broadcast',
        event: 'signal',
        payload: data
      });
    }
  }

  async handleSignalingData(data) {
    try {
      if (data.type === 'offer' && !this.isInitiator) {
        await this.peerConnection.setRemoteDescription(new RTCSessionDescription(data.offer));
        const answer = await this.peerConnection.createAnswer();
        await this.peerConnection.setLocalDescription(answer);
        this.sendSignalingData({
          type: 'answer',
          answer: answer
        });
      } else if (data.type === 'answer' && this.isInitiator) {
        await this.peerConnection.setRemoteDescription(new RTCSessionDescription(data.answer));
      } else if (data.type === 'ice-candidate') {
        await this.peerConnection.addIceCandidate(new RTCIceCandidate(data.candidate));
      } else if (data.type === 'end-call') {
        this.endCall(false); // End call without broadcasting since we received it
      }
    } catch (error) {
      console.error("Error handling signaling data:", error);
    }
  }

  async createOffer() {
    try {
      const offer = await this.peerConnection.createOffer();
      await this.peerConnection.setLocalDescription(offer);
      this.sendSignalingData({
        type: 'offer',
        offer: offer
      });
    } catch (error) {
      console.error("Error creating offer:", error);
    }
  }

  toggleAudio(enabled) {
    if (this.localStream) {
      this.localStream.getAudioTracks().forEach(track => {
        track.enabled = enabled;
      });
    }
  }

  toggleVideo(enabled) {
    if (this.localStream) {
      this.localStream.getVideoTracks().forEach(track => {
        track.enabled = enabled;
      });
    }
  }

  endCall(broadcast = true) {
    if (broadcast) {
      this.sendSignalingData({ type: 'end-call' });
    }

    if (this.peerConnection) {
      this.peerConnection.close();
      this.peerConnection = null;
    }

    if (this.localStream) {
      this.localStream.getTracks().forEach(track => track.stop());
      this.localStream = null;
    }

    if (this.channel) {
      supabase.removeChannel(this.channel);
      this.channel = null;
    }
  }
}

import React, { useEffect, useRef } from 'react';

const LocalVideo = ({ stream, isMuted, isCameraOff }) => {
  const videoRef = useRef(null);

  useEffect(() => {
    if (videoRef.current && stream) {
      videoRef.current.srcObject = stream;
    }
  }, [stream]);

  return (
    <div className="relative w-32 h-48 md:w-48 md:h-64 bg-surface-container-high rounded-xl overflow-hidden shadow-lg border-2 border-primary/20 transition-all z-10">
      {stream && !isCameraOff ? (
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted // Always mute local video to prevent echo
          className="w-full h-full object-cover mirror-mode"
          style={{ transform: 'scaleX(-1)' }}
        />
      ) : (
        <div className="w-full h-full flex items-center justify-center bg-surface-container-lowest">
          <span className="material-symbols-outlined text-4xl text-on-surface-variant">videocam_off</span>
        </div>
      )}

      <div className="absolute bottom-2 right-2 bg-black/60 backdrop-blur-md px-2 py-1 rounded text-[10px] font-bold text-white flex items-center gap-1">
        You
        {isMuted && <span className="material-symbols-outlined text-[14px] text-error">mic_off</span>}
      </div>
    </div>
  );
};

export default LocalVideo;

