import React, { useState, useEffect } from 'react';

const CallTimer = ({ startTime, status }) => {
  const [duration, setDuration] = useState(0);

  useEffect(() => {
    let interval;
    if (status === 'active' && startTime) {
      interval = setInterval(() => {
        setDuration(Math.floor((Date.now() - new Date(startTime).getTime()) / 1000));
      }, 1000);
    } else {
      setDuration(0);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [status, startTime]);

  const formatTime = (seconds) => {
    const m = Math.floor(seconds / 60).toString().padStart(2, '0');
    const s = (seconds % 60).toString().padStart(2, '0');
    return `${m}:${s}`;
  };

  if (status !== 'active') return null;

  return (
    <div className="absolute top-4 right-4 bg-black/50 backdrop-blur-md px-3 py-1.5 rounded-lg text-xs font-mono font-bold text-white shadow-sm z-20 flex items-center gap-2">
      <span className="material-symbols-outlined text-[14px]">timer</span>
      {formatTime(duration)}
    </div>
  );
};

export default CallTimer;

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { WebRTCManager } from '../../services/webrtc';
import { updateVideoCallStatus, endVideoCall } from '../../services/videoCallApi';
import LocalVideo from './LocalVideo';
import RemoteVideo from './RemoteVideo';
import VideoControls from './VideoControls';
import CallTimer from './CallTimer';

const VideoCall = ({ callData, isInitiator }) => {
  const navigate = useNavigate();
  const [localStream, setLocalStream] = useState(null);
  const [remoteStream, setRemoteStream] = useState(null);
  const [isMuted, setIsMuted] = useState(false);
  const [isCameraOff, setIsCameraOff] = useState(false);
  const [status, setStatus] = useState(callData?.status || 'waiting');
  const [error, setError] = useState(null);

  const webrtcManager = useRef(null);

  useEffect(() => {
    let mounted = true;

    const initializeMedia = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
        if (!mounted) {
          stream.getTracks().forEach(track => track.stop());
          return;
        }
        setLocalStream(stream);

        // Initialize WebRTC Manager
        webrtcManager.current = new WebRTCManager(
          callData._id,
          isInitiator,
          (stream) => {
            setRemoteStream(stream);
            setStatus('active');

            // Update MongoDB status if initiator
            if (isInitiator) {
              updateVideoCallStatus(callData._id, 'active').catch(console.error);
            }
          },
          (iceState) => {
            if (iceState === 'disconnected' || iceState === 'failed' || iceState === 'closed') {
              handleEndCall(false);
            }
          }
        );

        await webrtcManager.current.initialize(stream);

      } catch (err) {
        console.error("Media Error:", err);
        setError("Could not access camera/microphone. Please ensure permissions are granted.");
      }
    };

    initializeMedia();

    return () => {
      mounted = false;
      if (webrtcManager.current) {
        webrtcManager.current.endCall(false);
      }
      if (localStream) {
        localStream.getTracks().forEach(track => track.stop());
      }
    };
  }, [callData._id, isInitiator]);

  const toggleMute = () => {
    if (webrtcManager.current) {
      const newMutedState = !isMuted;
      webrtcManager.current.toggleAudio(!newMutedState);
      setIsMuted(newMutedState);
    }
  };

  const toggleCamera = () => {
    if (webrtcManager.current) {
      const newCameraState = !isCameraOff;
      webrtcManager.current.toggleVideo(!newCameraState);
      setIsCameraOff(newCameraState);
    }
  };

  const handleEndCall = async (manual = true) => {
    setStatus('ended');
    if (webrtcManager.current) {
      webrtcManager.current.endCall(manual);
    }

    try {
      if (manual) {
        await endVideoCall(callData._id);
      }
    } catch (err) {
      console.error("Error ending call in backend", err);
    }

    // Navigate back to the appropriate dashboard
    const role = localStorage.getItem('currentUser') ? JSON.parse(localStorage.getItem('currentUser')).role : null;
    if (role === 'doctor' || isInitiator) {
      navigate('/doctor-dashboard');
    } else {
      navigate('/owner-dashboard');
    }
  };

  if (error) {
    return (
      <div className="min-h-screen bg-surface flex flex-col items-center justify-center p-6 text-center">
        <span className="material-symbols-outlined text-6xl text-error mb-4">videocam_off</span>
        <h2 className="text-2xl font-bold text-on-surface mb-2">Media Access Error</h2>
        <p className="text-on-surface-variant max-w-md mb-6">{error}</p>
        <button onClick={() => navigate(-1)} className="bg-primary text-on-primary px-6 py-2.5 rounded-xl font-bold hover:bg-primary/90 transition-colors">
          Go Back
        </button>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 bg-black z-50 flex flex-col overflow-hidden font-sans">

      {/* Remote Video (Full Screen) */}
      <RemoteVideo 
        stream={remoteStream} 
        participantName={isInitiator ? callData.ownerName : callData.doctorName} 
        status={status}
      />

      {/* Top Header overlay */}
      <div className="absolute top-0 left-0 w-full p-4 bg-gradient-to-b from-black/70 to-transparent z-20 flex justify-between items-start pointer-events-none">
        <div>
          <h1 className="text-white font-headline-sm font-bold tracking-wide shadow-sm flex items-center gap-2">
            <span className="material-symbols-outlined text-[20px]">videocam</span> 
            Consultation
          </h1>
          <p className="text-white/70 text-xs font-bold uppercase tracking-wider">
            {isInitiator ? callData.patientName : callData.doctorName}
          </p>
        </div>
      </div>

      <CallTimer startTime={callData.startedAt || new Date().toISOString()} status={status} />

      {/* Local Video (PiP) */}
      <div className="absolute top-4 right-4 md:top-6 md:right-6 cursor-move z-30">
        <LocalVideo stream={localStream} isMuted={isMuted} isCameraOff={isCameraOff} />
      </div>

      {/* Controls */}
      <VideoControls 
        isMuted={isMuted}
        isCameraOff={isCameraOff}
        toggleMute={toggleMute}
        toggleCamera={toggleCamera}
        onEndCall={() => handleEndCall(true)}
      />
    </div>
  );
};

export default VideoCall;

import React, { useState, useEffect } from 'react';
import { useParams, useLocation, useNavigate } from 'react-router-dom';
import VideoCallWrapper from '../../components/video-call/VideoCall';
import { createVideoCall } from '../../services/videoCallApi';

const DoctorVideoCall = () => {
  const { appointmentId } = useParams();
  const location = useLocation();
  const navigate = useNavigate();
  const [callData, setCallData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // We expect the appointment details to be passed via location state
  const appointmentDetails = location.state?.appointment;

  useEffect(() => {
    const initCall = async () => {
      try {
        if (!appointmentId || !appointmentDetails) {
          throw new Error("Missing appointment details. Please start the call from the dashboard.");
        }

        // 1. Verify user is a doctor
        const userStr = localStorage.getItem('currentUser');
        if (!userStr) throw new Error("Not authenticated");

        const user = JSON.parse(userStr);
        if (user.role !== 'doctor' && user.role !== 'vet') {
          throw new Error("Unauthorized: Only doctors can initiate the call from this route.");
        }

        // 2. Create the MongoDB VideoCall record
        const payload = {
          appointmentId: appointmentId,
          doctorId: user._id || user.id,
          doctorName: user.name,
          ownerId: appointmentDetails.ownerId,
          ownerName: appointmentDetails.ownerName,
          patientId: appointmentDetails.petId,
          patientName: appointmentDetails.petName || 'Patient'
        };

        const response = await createVideoCall(payload);
        setCallData(response.videoCall || response.data);
      } catch (err) {
        console.error("Failed to initialize call:", err);
        setError(err.message || "Failed to initialize call. Ensure the backend is running.");
      } finally {
        setLoading(false);
      }
    };

    initCall();
  }, [appointmentId, appointmentDetails]);

  if (loading) {
    return (
      <div className="min-h-screen bg-surface flex flex-col items-center justify-center p-6 text-center">
        <span className="material-symbols-outlined animate-spin text-4xl text-primary mb-4">sync</span>
        <h2 className="text-xl font-bold text-on-surface">Initializing Secure Consultation...</h2>
        <p className="text-sm text-on-surface-variant mt-2">Connecting to signaling servers.</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-surface flex flex-col items-center justify-center p-6 text-center">
        <span className="material-symbols-outlined text-6xl text-error mb-4">error</span>
        <h2 className="text-2xl font-bold text-on-surface mb-2">Failed to Start Call</h2>
        <p className="text-on-surface-variant max-w-md mb-6">{error}</p>
        <button onClick={() => navigate('/doctor-dashboard')} className="bg-primary text-on-primary px-6 py-2.5 rounded-xl font-bold hover:bg-primary/90 transition-colors">
          Back to Dashboard
        </button>
      </div>
    );
  }

  return (
    <VideoCallWrapper callData={callData} isInitiator={true} />
  );
};

export default DoctorVideoCall;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import VideoCallWrapper from '../../components/video-call/VideoCall';
import { getVideoCallByAppointment } from '../../services/videoCallApi';

const OwnerVideoCall = () => {
  const { appointmentId } = useParams();
  const navigate = useNavigate();
  const [callData, setCallData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchCall = async () => {
      try {
        if (!appointmentId) throw new Error("Missing appointment ID.");

        // 1. Verify user is an owner
        const userStr = localStorage.getItem('currentUser');
        if (!userStr) throw new Error("Not authenticated");

        const user = JSON.parse(userStr);
        if (user.role && user.role !== 'owner') {
          throw new Error("Unauthorized access.");
        }

        // 2. Fetch the active VideoCall record from MongoDB
        const response = await getVideoCallByAppointment(appointmentId);

        if (!response.data || response.data.length === 0) {
           throw new Error("The doctor has not started this consultation yet.");
        }

        // Use the most recent active/waiting call
        const activeCall = response.data.find(c => c.status === 'waiting' || c.status === 'active');
        if (!activeCall) {
          throw new Error("The consultation has already ended or hasn't started.");
        }

        setCallData(activeCall);
      } catch (err) {
        console.error("Failed to fetch call:", err);
        setError(err.message || "Failed to join call. The doctor might not have started it yet.");
      } finally {
        setLoading(false);
      }
    };

    fetchCall();
  }, [appointmentId]);

  if (loading) {
    return (
      <div className="min-h-screen bg-surface flex flex-col items-center justify-center p-6 text-center">
        <span className="material-symbols-outlined animate-spin text-4xl text-primary mb-4">sync</span>
        <h2 className="text-xl font-bold text-on-surface">Connecting to Clinic...</h2>
        <p className="text-sm text-on-surface-variant mt-2">Checking if the doctor is ready.</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-surface flex flex-col items-center justify-center p-6 text-center">
        <span className="material-symbols-outlined text-6xl text-on-surface-variant mb-4">event_busy</span>
        <h2 className="text-2xl font-bold text-on-surface mb-2">Unable to Join</h2>
        <p className="text-on-surface-variant max-w-md mb-6">{error}</p>
        <button onClick={() => navigate('/appointments')} className="bg-primary text-on-primary px-6 py-2.5 rounded-xl font-bold hover:bg-primary/90 transition-colors shadow-sm">
          Return to Appointments
        </button>
      </div>
    );
  }

  return (
    <VideoCallWrapper callData={callData} isInitiator={false} />
  );
};

export default OwnerVideoCall;

