                  </div>

                  <div className="print-actions p-3 bg-surface-container border-t border-outline-variant flex justify-end gap-2">
                    <button onClick={() => handlePrint(cardId, false)} className="px-4 py-1.5 bg-surface-container-lowest border border-outline-variant rounded-lg text-xs font-bold text-on-surface-variant hover:bg-surface-container-low transition-colors flex items-center gap-1">
                      <span className="material-symbols-outlined text-[16px]">print</span> Print
