                    <button onClick={() => handlePrint(cardId, true)} className="px-4 py-1.5 bg-primary text-white rounded-lg text-xs font-bold hover:bg-surface-tint transition-colors flex items-center gap-1">
                      <span className="material-symbols-outlined text-[16px]">download</span> Download PDF
                    </button>
                  </div>
                </div>
              );
              })}

