const handlePrint = (id, downloadPdf = false, petName = 'Pet') => {
  const printElement = document.getElementById(`prescription-${id}`);
  if (!printElement) return;

  if (downloadPdf) {
    if (window.html2pdf) {
      const buttons = printElement.querySelector('.print-actions');
      if (buttons) buttons.style.display = 'none';

      const opt = {
        margin:       0.5,
        filename:     `Prescription_${petName}.pdf`,
        image:        { type: 'jpeg', quality: 0.98 },
        html2canvas:  { scale: 2 },
        jsPDF:        { unit: 'in', format: 'letter', orientation: 'portrait' }
      };

      window.html2pdf().set(opt).from(printElement).save().then(() => {
        if (buttons) buttons.style.display = 'flex';
      });
      return;
    } else {
      alert("In the print dialog, please select 'Save as PDF' as your Destination.");
    }
  }

  const clone = printElement.cloneNode(true);
  const buttons = clone.querySelector('.print-actions');
  if (buttons) buttons.remove();

