const handlePrint = (id, downloadPdf = false, petName = 'Pet') => {
  const printElement = document.getElementById(`prescription-${id}`);
  if (!printElement) return;

  if (downloadPdf) {
    if (window.html2pdf) {
      const buttons = printElement.querySelector('.print-actions');
      if (buttons) buttons.style.display = 'none';
      printElement.classList.remove('overflow-hidden');

      const opt = {
        margin:       0.5,
        filename:     `Prescription_${petName}.pdf`,
        image:        { type: 'jpeg', quality: 0.98 },
        html2canvas:  { scale: 2, useCORS: true, windowWidth: 1024 },
        jsPDF:        { unit: 'in', format: 'letter', orientation: 'portrait' }
      };

      window.html2pdf().set(opt).from(printElement).save().then(() => {
        printElement.classList.add('overflow-hidden');
        if (buttons) buttons.style.display = 'flex';
      });
      return;
    } else {
      alert("In the print dialog, please select 'Save as PDF' as your Destination.");
    }
  }

  const clone = printElement.cloneNode(true);
  const buttons = clone.querySelector('.print-actions');
  if (buttons) buttons.remove();

  const printWindow = window.open('', '', 'height=800,width=800');
  printWindow.document.write('<html><head><title>Prescription</title>');
  printWindow.document.write('<script src="https://cdn.tailwindcss.com"></script>');
  printWindow.document.write('<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@24,400,0,0" />');
  printWindow.document.write('<style>body{padding:20px;} @media print { @page { margin: 0; } body { padding: 1cm; } }</style>');
  printWindow.document.write('</head><body>');
  printWindow.document.write(clone.outerHTML);
  printWindow.document.write('</body></html>');
  printWindow.document.close();

  setTimeout(() => {
    printWindow.focus();
    printWindow.print();
  }, 1500);
};

