  if (window.html2pdf) {
    const buttons = printElement.querySelector('.print-actions');
    if (buttons) buttons.style.display = 'none';

    // Remove overflow hidden to avoid clipping
    printElement.classList.remove('overflow-hidden');

    // Temporarily inline styles to help html2canvas render tailwind css variables
    const allElements = printElement.querySelectorAll('*');
    const originalStyles = [];
    allElements.forEach((el, i) => {
      const comp = window.getComputedStyle(el);
      originalStyles.push({ el, bg: el.style.backgroundColor, col: el.style.color, bor: el.style.borderColor });
      // Force inline standard colors instead of css variables for canvas
      if (comp.backgroundColor && comp.backgroundColor !== 'rgba(0, 0, 0, 0)') el.style.backgroundColor = comp.backgroundColor;
      if (comp.color) el.style.color = comp.color;
      if (comp.borderColor) el.style.borderColor = comp.borderColor;
    });

    const opt = {
      margin:       0.3,
      filename:     `Prescription_${petName}.pdf`,
      image:        { type: 'jpeg', quality: 1.0 },
      html2canvas:  { scale: 2, useCORS: true, letterRendering: true, windowWidth: 1024 },
      jsPDF:        { unit: 'in', format: 'letter', orientation: 'portrait' }
    };

    window.html2pdf().set(opt).from(printElement).save().then(() => {
      printElement.classList.add('overflow-hidden');
      if (buttons) buttons.style.display = 'flex';
      // Restore original styles
      originalStyles.forEach(item => {
        item.el.style.backgroundColor = item.bg;
        item.el.style.color = item.col;
        item.el.style.borderColor = item.bor;
      });
    });
    return;
  } else {
    alert("PDF Generator is still loading, please wait a second and try again.");
    return;
  }
}

