args.ReplacementContent:
if (downloadPdf) {
  if (window.html2pdf) {
    // Clone the element so we don't mess with the visible UI
    const clone = printElement.cloneNode(true);
    const buttons = clone.querySelector('.print-actions');
    if (buttons) buttons.remove();
    clone.classList.remove('overflow-hidden');

    // Append clone to a hidden container in the body so it inherits styles
    const hiddenContainer = document.createElement('div');
    hiddenContainer.style.position = 'absolute';
    hiddenContainer.style.top = '-9999px';
    hiddenContainer.style.left = '-9999px';
    hiddenContainer.style.width = '1024px'; // Force desktop width
    hiddenContainer.appendChild(clone);
    document.body.appendChild(hiddenContainer);

    const opt = {
      margin:       0.3,
      filename:     `Prescription_${petName}.pdf`,
      image:        { type: 'jpeg', quality: 1.0 },
      html2canvas:  { scale: 2, useCORS: true, letterRendering: true, windowWidth: 1024 },
      jsPDF:        { unit: 'in', format: 'letter', orientation: 'portrait' }
    };

    window.html2pdf().set(opt).from(clone).save().then(() => {
      // Cleanup
      document.body.removeChild(hiddenContainer);
    }).catch((err) => {
      console.error("PDF generation failed:", err);
      if (document.body.contains(hiddenContainer)) {
        document.body.removeChild(hiddenContainer);
      }
    });
    return;
  } else {
    alert("PDF Generator is still loading, please wait a second and try again.");
    return;
  }
}

