if (downloadPdf) {
  if (!window.html2pdf) {
    alert("PDF Generator is still loading, please wait a second and try again.");
    return;
  }

  const clone = printElement.cloneNode(true);
  const buttons = clone.querySelector('.print-actions');
  if (buttons) buttons.remove();

  clone.classList.remove('overflow-hidden', 'overflow-auto', 'overflow-y-auto', 'overflow-x-auto', 'h-full', 'h-screen');
  clone.style.height = 'auto';
  clone.style.maxHeight = 'none';
  clone.style.minHeight = '0';
  clone.style.overflow = 'visible';
  clone.style.width = '100%';
  clone.style.maxWidth = '100%';
  clone.style.boxSizing = 'border-box';

  const allElements = clone.querySelectorAll('*');
  allElements.forEach((el) => {
    const computed = window.getComputedStyle(el);
    if (computed.height !== 'auto' && computed.overflow !== 'visible') {
      el.style.maxHeight = 'none';
    }
    if (computed.overflow === 'hidden' || computed.overflowY === 'hidden' || computed.overflowY === 'auto') {
      el.style.overflow = 'visible';
    }
    el.style.maxHeight = 'none';
  });

  const container = document.createElement('div');
  container.style.width = '190mm';
  container.style.maxWidth = '190mm';
  container.style.margin = '0 auto';
  container.style.background = '#ffffff';
  container.style.boxSizing = 'border-box';

  container.appendChild(clone);
  document.body.appendChild(container);

  const waitForImages = async () => {
    const images = clone.querySelectorAll('img');
    await Promise.all(
      Array.from(images).map((img) => {
        if (img.complete) return Promise.resolve();
        return new Promise((resolve) => {
          img.onload = resolve;
          img.onerror = resolve;
        });
      })
    );
    if (document.fonts && document.fonts.ready) {
      await document.fonts.ready;
    }
    await new Promise((resolve) => requestAnimationFrame(() => resolve()));
  };

  waitForImages().then(() => {
    console.log({
      width: clone.scrollWidth,
      height: clone.scrollHeight,
      clientWidth: clone.clientWidth,
      clientHeight: clone.clientHeight,
      rect: clone.getBoundingClientRect()
    });

    const opt = {
      margin: [8, 8, 8, 8],
      filename: `Prescription_${petName}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: {
        scale: 2,
        useCORS: true,
        allowTaint: false,
        backgroundColor: '#ffffff',
        scrollX: 0,
        scrollY: 0
      },
      jsPDF: {
        unit: 'mm',
        format: 'a4',
        orientation: 'portrait'
      },
      pagebreak: { mode: ['css', 'legacy'] }
    };

    window.html2pdf().set(opt).from(container).save().then(() => {
      if (document.body.contains(container)) {
        document.body.removeChild(container);
      }
    }).catch((err) => {
      console.error('PDF generation failed:', err);
      if (document.body.contains(container)) {
        document.body.removeChild(container);
      }
    });
  });

  return;
}

