const handlePrint = (id, downloadPdf = false, petName = "Pet") => {
  const printElement = document.getElementById(`prescription-${id}`);

  if (!printElement) {
    console.error("Prescription element not found:", id);
    return;
  }

  if (downloadPdf) {
    if (!window.html2pdf) {
      alert("PDF Generator is still loading, please wait a second and try again.");
      return;
    }

    // Clone original element
    const clone = printElement.cloneNode(true);

    // Remove print buttons/actions
    clone.querySelectorAll(".print-actions").forEach((el) => {
      el.remove();
    });

    // Remove common height/overflow restrictions
    clone.classList.remove(
      "overflow-hidden",
      "overflow-auto",
      "overflow-y-auto",
      "overflow-x-auto",
      "h-full",
      "max-h-full"
    );

    // Force PDF content to use full available height
    clone.style.height = "auto";
    clone.style.maxHeight = "none";
    clone.style.minHeight = "0";
    clone.style.overflow = "visible";
    clone.style.width = "100%";
    clone.style.maxWidth = "100%";
    clone.style.boxSizing = "border-box";

    // Hidden container wrapper using exact user specs
    const container = document.createElement("div");
    // Use absolute positioning at 0,0 to prevent viewport clipping
    container.style.position = "absolute";
    container.style.left = "0";
    container.style.top = "0";
    container.style.width = "190mm";
    container.style.maxWidth = "190mm";
    container.style.margin = "0 auto";
    container.style.background = "#ffffff";
    container.style.boxSizing = "border-box";
    container.style.zIndex = "1000"; // Render over UI briefly

    container.appendChild(clone);
    document.body.appendChild(container);

    // Force all child elements to avoid clipping
    const allElements = clone.querySelectorAll("*");
    allElements.forEach((el) => {
      const computed = window.getComputedStyle(el);
      if (computed.height !== "auto" && computed.overflow !== "visible") {
        el.style.maxHeight = "none";
      }
      if (computed.overflow === "hidden" || computed.overflowY === "hidden" || computed.overflowY === "auto") {
        el.style.overflow = "visible";
      }
      el.style.maxHeight = "none";
    });

    const options = {
      margin: [8, 8, 8, 8],
      filename: `Prescription_${petName.replace(/[^a-zA-Z0-9_-]/g, "_")}.pdf`,
      image: {
        type: "jpeg",
        quality: 0.98,
      },
      html2canvas: {
        scale: 2,
        useCORS: true,
        allowTaint: false,
        backgroundColor: "#ffffff",
        scrollX: 0,
        scrollY: 0,
        onclone: (clonedDocument) => {
          // Apply responsive PDF fixes inside canvas if needed
          const clonedCard = clonedDocument.getElementById(`prescription-${id}`);
          if (clonedCard) {
            clonedCard.style.width = "190mm";
            clonedCard.style.maxWidth = "190mm";
            clonedCard.style.margin = "0 auto";
            clonedCard.style.height = "auto";
            clonedCard.style.maxHeight = "none";
            clonedCard.style.overflow = "visible";
          }
        }
      },
      jsPDF: {
        unit: "mm",
        format: "a4",
        orientation: "portrait",
        compress: true,
      },
      pagebreak: {
        mode: ["css", "legacy"],
        avoid: [".prescription-section", ".signature-section", ".medicine-row"],
      },
    };

    const waitForImages = async () => {
      const images = clone.querySelectorAll("img");
      await Promise.all(
        Array.from(images).map((img) => {
          if (img.complete) return Promise.resolve();
          return new Promise((resolve) => {
            img.onload = resolve;
            img.onerror = resolve;
          });
        })
      );
      if (document.fonts && document.fonts.ready) {
        await document.fonts.ready;
      }
      await new Promise((resolve) => requestAnimationFrame(() => resolve()));
    };

    waitForImages().then(() => {
      console.log({
        width: clone.scrollWidth,
        height: clone.scrollHeight,
        clientWidth: clone.clientWidth,
        clientHeight: clone.clientHeight,
        rect: clone.getBoundingClientRect()
      });

      window.html2pdf().set(options).from(container).save().then(() => {
        if (document.body.contains(container)) {
          document.body.removeChild(container);
        }
      }).catch((error) => {
        console.error("PDF generation failed:", error);
        if (document.body.contains(container)) {
          document.body.removeChild(container);
        }
        alert("Unable to generate PDF. Please try again.");
      });
    });

    return;
  }

  // --- Restore normal Print logic ---
  const clone = printElement.cloneNode(true);
  const buttons = clone.querySelector('.print-actions');
  if (buttons) buttons.remove();

  const printWindow = window.open('', '', 'height=800,width=800');
  printWindow.document.write('<html><head><title>Prescription</title>');
  printWindow.document.write('<script src="https://cdn.tailwindcss.com"></script>');
  printWindow.document.write('<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@24,400,0,0" />');
  printWindow.document.write('<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Dancing+Script:wght@700&display=swap" rel="stylesheet"/>');
  printWindow.document.write(`
    <script>
      tailwind.config = {
        theme: { extend: { colors: { primary: '#12635a', 'on-surface': '#191c1b', 'surface-variant': '#dae5e1', 'on-surface-variant': '#3f4947', outline: '#6f7977', 'outline-variant': '#bec9c6', 'surface-container-lowest': '#ffffff', 'surface-container-low': '#f4f5f9', 'surface-container': '#eceee9' } } }
      }
    </script>
  `);
  printWindow.document.write('<style>body{padding:20px; font-family: "Inter", sans-serif;} @media print { @page { margin: 0; } body { padding: 1cm; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; } }</style>');
  printWindow.document.write('</head><body>');
  printWindow.document.write(clone.outerHTML);
  printWindow.document.write('</body></html>');
  printWindow.document.close();

  setTimeout(() => {
    printWindow.focus();
    printWindow.print();
  }, 1500);
};

