const handlePrint = (id, downloadPdf = false, petName = "Pet") => {
  const printElement = document.getElementById(`prescription-${id}`);

  if (!printElement) {
    console.error("Prescription element not found:", id);
    return;
  }

  clone.querySelectorAll(".print-actions").forEach((el) => {
    el.remove();
  });

  /*
   * Remove common height/overflow restrictions.
   * This is important when the original UI has fixed-height cards.
   */
  clone.classList.remove(
    "overflow-hidden",
    "overflow-auto",
    "overflow-y-auto",
    "overflow-x-auto",
    "h-full",
    "max-h-full"
  );

  // Force PDF content to use full available height
  clone.style.height = "auto";
  clone.style.maxHeight = "none";
  clone.style.minHeight = "0";
  clone.style.overflow = "visible";
  clone.style.width = "100%";
  clone.style.maxWidth = "100%";
  clone.style.boxSizing = "border-box";

  /*
   * Hidden container
   *
   * Don't use z-index:-9999.
   * html2canvas can sometimes ignore/clips elements
   * that are behind the document.
   */
  const container = document.createElement("div");

  container.style.position = "fixed";
  container.style.left = "0";
  container.style.top = "0";
  container.style.width = "794px"; // A4 width at ~96 DPI
  container.style.minHeight = "1123px";
  container.style.padding = "20px";
  container.style.background = "#ffffff";
  container.style.boxSizing = "border-box";

  // Keep it outside visible UI but still renderable by html2canvas
  container.style.opacity = "1";
  container.style.pointerEvents = "none";

  // Do NOT use display:none
  // Do NOT use visibility:hidden
  // Do NOT use z-index:-9999

  container.appendChild(clone);
  document.body.appendChild(container);

  /*
   * Force all child elements to avoid clipping.
   */
  const allElements = clone.querySelectorAll("*");

  allElements.forEach((el) => {
    const element = el;

    const computed = window.getComputedStyle(element);

    // Remove fixed height restrictions
    if (
      computed.height !== "auto" &&
      computed.overflow !== "visible"
    ) {
      element.style.maxHeight = "none";
    }

    // Prevent content clipping
    if (
      computed.overflow === "hidden" ||
      computed.overflowY === "hidden" ||
      computed.overflowY === "auto"
    ) {
      element.style.overflow = "visible";
    }

    // Remove max-height
    element.style.maxHeight = "none";
  });

  /*
   * PDF options
   */
  const options = {
    margin: [10, 10, 10, 10],

    filename: `Prescription_${petName.replace(
      /[^a-zA-Z0-9_-]/g,
      "_"
    )}.pdf`,

    image: {
      type: "jpeg",
      quality: 0.98,
    },

    html2canvas: {
      scale: 2,
      useCORS: true,
      allowTaint: true,

      /*
       * Important:
       * Don't force a short canvas height.
       */
      windowWidth: 794,
      scrollX: 0,
      scrollY: 0,

      backgroundColor: "#ffffff",

      /*
       * Prevent rendering based on viewport clipping.
       */
      onclone: (clonedDocument) => {
        const clonedElement =
          clonedDocument.getElementById(
            `prescription-${id}`
          );

        if (!clonedElement) return;

        clonedElement.style.height = "auto";
        clonedElement.style.maxHeight = "none";
        clonedElement.style.overflow = "visible";

        const children =
          clonedElement.querySelectorAll("*");

        children.forEach((child) => {
          child.style.maxHeight = "none";

          if (
            child.style.overflow === "hidden" ||
            child.style.overflow === "auto"
          ) {
            child.style.overflow = "visible";
          }
        });
      },
    },

    jsPDF: {
      unit: "mm",
      format: "a4",
      orientation: "portrait",
      compress: true,
    },

    pagebreak: {
      mode: ["css", "legacy"],
      avoid: [
        ".prescription-section",
        ".signature-section",
        ".medicine-row",
      ],
    },
  };

  /*
   * Wait for images/fonts before generating PDF.
   */
  const waitForImages = async () => {
    const images = clone.querySelectorAll("img");

    await Promise.all(
      Array.from(images).map((img) => {
        if (img.complete) {
          return Promise.resolve();
        }

        return new Promise((resolve) => {
          img.onload = resolve;
          img.onerror = resolve;
        });
      })
    );

    // Wait for fonts
    if (document.fonts?.ready) {
      await document.fonts.ready;
    }

    // Give browser one render cycle
    await new Promise((resolve) =>
      requestAnimationFrame(() => resolve())
    );
  };

  waitForImages()
    .then(() => {
      return window
        .html2pdf()
        .set(options)
        .from(clone)
        .save();
    })
    .then(() => {
      if (document.body.contains(container)) {
        document.body.removeChild(container);
      }
    })
    .catch((error) => {
      console.error("PDF generation failed:", error);

      if (document.body.contains(container)) {
        document.body.removeChild(container);
      }

      alert(
        "Unable to generate PDF. Please try again."
      );
    });
};

